# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/steps/pre-deploy-mule-application.yml
#   step   : "Publish to Exchange (CH2/RTF)" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
# The shellcheck codes disabled above come from constructs inherited verbatim from that source.
#
# Inputs (environment):
#   MDF_ARTIFACTS_DIR       <- ${{ parameters.artifactsDir }}  [default: $(Pipeline.Workspace)/mule-artifacts]
#   MDF_ARTIFACT_ID         <- ${{ parameters.artifactId }}  [required]
#   MDF_BEARER_TOKEN        <- ${{ parameters.bearerToken }}  [default: (empty)]
