#   MDF_CLASSIFIER          <- ${{ parameters.classifier }}  [default: mule-application]
#   MDF_PARENT_ARTIFACT_ID  <- $(preDeploy.parentArtifactId)  [default: (empty)]
#   MDF_PARENT_GROUP_ID     <- $(preDeploy.parentGroupId)  [default: (empty)]
#   MDF_PARENT_VERSION      <- $(preDeploy.parentVersion)  [default: (empty)]
#   MDF_VERSION             <- ${{ parameters.version }}  [required]
# Outputs: exchangeVersion (output), exchangeGroupId (output), exchangeArtifactId (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_ARTIFACTS_DIR=$(ci_pipeline_workspace)/mule-artifacts}"
: "${MDF_ARTIFACT_ID?MDF_ARTIFACT_ID is required (Azure parameter artifactId)}"
: "${MDF_BEARER_TOKEN=}"
: "${MDF_BG_ID=}"
: "${MDF_CLASSIFIER=mule-application}"
: "${MDF_PARENT_ARTIFACT_ID=}"
: "${MDF_PARENT_GROUP_ID=}"
: "${MDF_PARENT_VERSION=}"
: "${MDF_VERSION?MDF_VERSION is required (Azure parameter version)}"

# >>> extracted body
set -euo pipefail
ARTIFACT_ID="${MDF_ARTIFACT_ID}"
VERSION="${MDF_VERSION}"
ARTIFACTS_DIR="${MDF_ARTIFACTS_DIR}"
BG_ID="${MDF_BG_ID}"
CLASSIFIER="${MDF_CLASSIFIER}"
JAR_FILE="$ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}.jar"
PARENT_GROUP_ID="${MDF_PARENT_GROUP_ID}"
PARENT_ARTIFACT_ID="${MDF_PARENT_ARTIFACT_ID}"
PARENT_VERSION="${MDF_PARENT_VERSION}"

echo "[DEBUG] ============================================"
echo "[DEBUG] PUBLISH TO EXCHANGE START"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   artifactId=$ARTIFACT_ID"
echo "[DEBUG]   version=$VERSION"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   classifier=$CLASSIFIER"
echo "[DEBUG]   JAR_FILE=$JAR_FILE (exists=$([ -f "$JAR_FILE" ] && echo 'yes' || echo 'no'))"
echo "[DEBUG]   parentPOM=${PARENT_GROUP_ID}:${PARENT_ARTIFACT_ID}:${PARENT_VERSION}"
echo "[DEBUG] ============================================"

# Generate timestamped deploy version for Exchange uniqueness
TIMESTAMP=$(date +%Y%m%d%H%M%S)
echo "[DEBUG] Generated timestamp: $TIMESTAMP"
if [[ "$VERSION" == *"SNAPSHOT"* ]]; then
  BASE_VERSION=$(echo "$VERSION" | sed 's/-SNAPSHOT//')
  DEPLOY_VERSION="${BASE_VERSION}-SNAPSHOT-${TIMESTAMP}"
  echo "[DEBUG] SNAPSHOT version detected. BASE_VERSION=$BASE_VERSION"
else
  DEPLOY_VERSION="${VERSION}-${TIMESTAMP}"
  echo "[DEBUG] Release version detected."
fi
echo "[DEBUG] DEPLOY_VERSION=$DEPLOY_VERSION"

# Overwrite deploy-pom.xml with timestamped version for Exchange
DEPLOY_POM="$ARTIFACTS_DIR/deploy-pom.xml"
PARENT_XML=""
if [[ -n "$PARENT_GROUP_ID" && -n "$PARENT_ARTIFACT_ID" && -n "$PARENT_VERSION" ]]; then
  PARENT_XML="  <parent>\n    <groupId>${PARENT_GROUP_ID}</groupId>\n    <artifactId>${PARENT_ARTIFACT_ID}</artifactId>\n    <version>${PARENT_VERSION}</version>\n  </parent>"
fi

{
  echo '<?xml version="1.0" encoding="UTF-8"?>'
  echo '<project>'
  echo '  <modelVersion>4.0.0</modelVersion>'
  if [[ -n "$PARENT_XML" ]]; then
    printf '%b\n' "$PARENT_XML"
  fi
  echo "  <groupId>${BG_ID}</groupId>"
  echo "  <artifactId>${ARTIFACT_ID}</artifactId>"
  echo "  <version>${DEPLOY_VERSION}</version>"
  echo "  <name>${ARTIFACT_ID}</name>"
  echo '  <packaging>mule-application</packaging>'
  echo '</project>'
} > "$DEPLOY_POM"
echo "[DEBUG] Deploy POM overwritten with Exchange version: $DEPLOY_VERSION"
echo "[DEBUG] Deploy POM content:"
echo "[DEBUG] $(cat "$DEPLOY_POM")"

echo "Publishing to Exchange: ${BG_ID}/${ARTIFACT_ID}/${DEPLOY_VERSION}"
echo "[DEBUG] Exchange API URL: https://anypoint.mulesoft.com/exchange/api/v2/organizations/${BG_ID}/assets/${BG_ID}/${ARTIFACT_ID}/${DEPLOY_VERSION}"
echo "[DEBUG] JAR file size: $(stat -f%z "$JAR_FILE" 2>/dev/null || stat --printf="%s" "$JAR_FILE" 2>/dev/null) bytes"

response=$(curl -s -X POST \
  -H "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
  -H "x-sync-publication: true" \
  -F "files.pom=@${DEPLOY_POM}" \
  -F "files.mule-application.jar=@${JAR_FILE}" \
  "https://anypoint.mulesoft.com/exchange/api/v2/organizations/${BG_ID}/assets/${BG_ID}/${ARTIFACT_ID}/${DEPLOY_VERSION}")

echo "[DEBUG] Exchange publish response: $response"

if echo "$response" | jq -e '.assetId' &>/dev/null; then
  echo "Successfully published to Exchange."
  echo "[DEBUG] Published assetId: $(echo "$response" | jq -r '.assetId')"
else
  ci_log_error "Failed to publish to Exchange."
  echo "Response: $response"
  exit 1
fi

ci_set_var exchangeVersion "$DEPLOY_VERSION"
ci_set_var exchangeGroupId "$BG_ID"
ci_set_var exchangeArtifactId "$ARTIFACT_ID"
echo "[DEBUG] Outputs: exchangeVersion=$DEPLOY_VERSION, exchangeGroupId=$BG_ID, exchangeArtifactId=$ARTIFACT_ID"
echo "[DEBUG] PUBLISH TO EXCHANGE COMPLETE"
